import { useState, useEffect } from 'react';
import { useLoaderData } from 'react-router-dom';
import { motion, AnimatePresence } from 'motion/react';
import { Helmet } from '@dr.pogodin/react-helmet';
import { Skeleton } from '@/components/ui/skeleton';
import type { Product } from '../server/api/products/GET';

type Category = 'all' | 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

const categories: { value: Category; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'pottery', label: 'Pottery' },
  { value: 'textiles', label: 'Textiles' },
  { value: 'woodwork', label: 'Woodwork' },
  { value: 'jewelry', label: 'Jewelry' },
];

function ProductCard({ product, index }: { product: Product; index: number }) {
  return (
    <motion.article
      layout
      initial={{ opacity: 0, y: 24 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 12 }}
      transition={{ duration: 0.35, delay: index * 0.06, ease: 'easeOut' as const }}
      className="group cursor-pointer"
    >
      <div className="overflow-hidden rounded-sm aspect-square mb-4 bg-muted relative">
        <img
          src={product.image}
          alt={product.name}
          className="w-full h-full object-cover transition-transform duration-500 ease-out group-hover:scale-105"
          loading="lazy"
        />
        {product.featured && (
          <span className="absolute top-3 left-3 bg-primary text-primary-foreground text-xs px-2 py-1 uppercase tracking-wider font-medium">
            Featured
          </span>
        )}
      </div>
      <div className="space-y-1.5">
        <span className="text-xs uppercase tracking-widest text-primary font-medium">
          {product.category}
        </span>
        <h3 className="font-heading text-lg text-foreground leading-snug group-hover:text-primary transition-colors">
          {product.name}
        </h3>
        <p className="text-sm text-foreground/60 leading-relaxed line-clamp-2">
          {product.description}
        </p>
        <p className="text-foreground font-semibold pt-1">${product.price}</p>
      </div>
    </motion.article>
  );
}

function ProductSkeleton() {
  return (
    <div className="space-y-4">
      <Skeleton className="aspect-square w-full rounded-sm" />
      <Skeleton className="h-3 w-16" />
      <Skeleton className="h-5 w-3/4" />
      <Skeleton className="h-4 w-full" />
      <Skeleton className="h-4 w-1/4" />
    </div>
  );
}

export default function ProductsPage() {
  const initialProducts = useLoaderData() as Product[];
  const [activeCategory, setActiveCategory] = useState<Category>('all');
  const [products, setProducts] = useState<Product[]>(initialProducts || []);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!initialProducts) return;
    setProducts(initialProducts);
  }, [initialProducts]);

  const handleCategoryChange = async (cat: Category) => {
    setActiveCategory(cat);
    setLoading(true);
    try {
      const url = cat === 'all' ? '/api/products' : `/api/products?category=${cat}`;
      const res = await fetch(url);
      const data: Product[] = await res.json();
      setProducts(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <Helmet>
        <title>Shop All Products — Artisan Goods Co.</title>
        <meta
          name="description"
          content="Browse our full collection of handmade pottery, textiles, woodwork, and jewelry. Each piece is crafted by skilled artisans."
        />
      </Helmet>

      {/* Page Header */}
      <div className="bg-muted py-16 md:py-20">
        <div className="container mx-auto px-6 lg:px-8">
          <p className="text-xs uppercase tracking-widest text-primary mb-3 font-medium">
            The Collection
          </p>
          <h1 className="font-heading text-5xl md:text-6xl text-foreground">
            All Products
          </h1>
          <p className="mt-4 text-foreground/60 max-w-md leading-relaxed">
            Every item is made by hand, in small batches, by artisans who care deeply about their craft.
          </p>
        </div>
      </div>

      <div className="container mx-auto px-6 lg:px-8 py-12">
        {/* Category Filters */}
        <div className="flex flex-wrap gap-2 mb-12">
          {categories.map((cat) => (
            <button
              key={cat.value}
              onClick={() => handleCategoryChange(cat.value)}
              className={`px-5 py-2 text-sm font-medium rounded-full border transition-all duration-200 ${
                activeCategory === cat.value
                  ? 'bg-primary text-primary-foreground border-primary'
                  : 'bg-background text-foreground/60 border-border hover:border-primary hover:text-primary'
              }`}
            >
              {cat.label}
            </button>
          ))}
        </div>

        {/* Product Count */}
        <p className="text-sm text-foreground/40 mb-8">
          {loading ? 'Loading…' : `${products.length} piece${products.length !== 1 ? 's' : ''}`}
        </p>

        {/* Product Grid */}
        {loading ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-10">
            {Array.from({ length: 6 }).map((_, i) => (
              <ProductSkeleton key={i} />
            ))}
          </div>
        ) : (
          <AnimatePresence mode="popLayout">
            <motion.div
              key={activeCategory}
              className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-10"
            >
              {products.map((product, i) => (
                <ProductCard key={product.id} product={product} index={i} />
              ))}
            </motion.div>
          </AnimatePresence>
        )}

        {products.length === 0 && !loading && (
          <div className="text-center py-20">
            <p className="text-foreground/40 text-lg">No products found in this category.</p>
          </div>
        )}
      </div>
    </>
  );
}

